use anyhow::{bail, Context, Result};

use crate::config::MachineConfig;

// The shared seam, re-exported at its historical path so no call site moved
// when R859-F2's extraction landed. `cloud::provider::floating_ip::X` still
// resolves for every X the old module defined.
pub use floating_ip::{
    on_ingress_owner_changed, plan_ingress_owner_effect, provider_has_floating_ip_adapter,
    reconcile_assignment, resolve_ingress_owner, supported_floating_ip_providers,
    FloatingIpAssignOutcome, FloatingIpMachine, FloatingIpProvider, FloatingIpState,
    FloatingIpTarget, IngressOwnerEffect, OwnerLiveness, QuorumHealth, FLOATING_IP_PROVIDERS,
};

/// Narrow a [`MachineConfig`] to the five facts floating-IP mobility reads.
///
/// The boundary conversion, and the reason the shared crate needs nothing from
/// `cloud`. Written as a function rather than a `From` impl because the source
/// is a borrow and the target is owned, and `From<&MachineConfig>` reads as a
/// cheap coercion at call sites where it is actually five clones.
pub fn machine_facts(machine: &MachineConfig) -> FloatingIpMachine {
    FloatingIpMachine {
        name: machine.name.clone(),
        provider: machine.provider.clone(),
        location: machine.location.clone(),
        region: machine.region.clone(),
        ingress_floating_ip: machine.ingress_floating_ip.clone(),
    }
}

/// Resolve `machine.provider` to a live [`FloatingIpProvider`] — the registry
/// R594-F5 left out.
///
/// Without this the three adapters were unreachable from any caller holding a
/// [`MachineConfig`]: each knows its own wire format, and nothing mapped a
/// declared provider onto one. Credentials come from the same
/// `fob`-then-env source [`super::HetznerDriver::from_default_sources`] uses,
/// so a camp that can already drive a provider can drive its floating IPs with
/// no extra configuration.
///
/// Stayed in `cloud` when the seam moved out (R859-F2): the slot/env columns of
/// [`FLOATING_IP_PROVIDERS`] are read here and the adapters are constructed
/// here, and neither `fob` nor the vendor HTTP clients belong in a crate that
/// links into the fleet daemon.
///
/// Two distinct failures, kept distinct because they want different fixes: a
/// provider with no adapter is a *declaration* error (nothing will ever move
/// that IP), while a missing credential is an *environment* error (the
/// declaration is fine, this process cannot act on it).
pub fn floating_ip_provider_for(machine: &MachineConfig) -> Result<Box<dyn FloatingIpProvider>> {
    let Some((_, slot, env)) = FLOATING_IP_PROVIDERS
        .iter()
        .find(|(id, _, _)| *id == machine.provider)
    else {
        bail!(
            "machine {:?} declares provider {:?}, which has no floating-IP adapter — \
             floating/reserved IPs are implemented for {} only",
            machine.name,
            machine.provider,
            supported_floating_ip_providers(),
        );
    };
    let token = fob::get_or_env(slot, env)
        .with_context(|| format!("reading {slot} for machine {:?}", machine.name))?
        .with_context(|| {
            format!(
                "machine {:?} needs {:?} credentials to move its floating IP, but neither the \
                 `{slot}` vault slot nor ${env} is set",
                machine.name, machine.provider,
            )
        })?;
    // R859-F3: the provider-id → client match lives in the adapters crate now,
    // so `yubaba`'s effector and this constructor build the same client from the
    // same table. What stays here is only the half `fob` is needed for.
    floating_ip_adapters::adapter_for(&machine.provider, &token).with_context(|| {
        format!(
            "building the floating-IP adapter for machine {:?}",
            machine.name
        )
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn machine(name: &str) -> MachineConfig {
        MachineConfig {
            name: name.into(),
            provider: "fake".into(),
            location: None,
            server_type: None,
            hosts_mirrors: vec![],
            mesh_tags: vec![],
            region: None,
            zone: None,
            arch: None,
            bucket: None,
            vendor: None,
            nickname: None,
            legacy_hostkey_fingerprint: None,
            registration: Default::default(),
            ssh_keys: vec![],
            cloudflared: None,
            hosts_operator_bridge: false,
            connect: None,
            allocatable: None,
            taints: vec![],
            sovereign_group: None,
            sovereign_role: None,
            ingress_floating_ip: None,
        }
    }

    /// The declaration error and the environment error are different failures
    /// wanting different fixes, so they must not collapse into one message.
    #[test]
    fn a_provider_with_no_adapter_is_refused_by_name_before_any_credential_lookup() {
        let mut m = machine("us-west-002");
        m.provider = "digitalocean".into();
        let err = match floating_ip_provider_for(&m) {
            Ok(_) => panic!("digitalocean has no floating-IP adapter but the registry built one"),
            Err(e) => e,
        };
        let msg = format!("{err:#}");
        assert!(msg.contains("us-west-002"), "{msg}");
        assert!(msg.contains("digitalocean"), "{msg}");
        assert!(
            msg.contains("hetzner") && msg.contains("ovh") && msg.contains("vultr"),
            "the refusal should name what IS supported: {msg}"
        );
    }

    /// The boundary conversion is the only thing standing between `cloud`'s
    /// machine declarations and a crate that cannot see them, so a field
    /// dropped here would silently disable a failover path rather than fail to
    /// compile — `ingress_floating_ip` going missing reads exactly like "this
    /// machine has no floating IP", which is a supported shape.
    #[test]
    fn machine_facts_carries_every_field_the_floating_ip_layer_reads() {
        let mut m = machine("us-east-001");
        m.provider = "hetzner".into();
        m.location = Some("iad".into());
        m.region = Some("us-east".into());
        m.ingress_floating_ip = Some("fip-42".into());

        let facts = machine_facts(&m);
        assert_eq!(facts.name, "us-east-001");
        assert_eq!(facts.provider, "hetzner");
        assert_eq!(facts.location.as_deref(), Some("iad"));
        assert_eq!(facts.region.as_deref(), Some("us-east"));
        assert_eq!(facts.ingress_floating_ip.as_deref(), Some("fip-42"));
        // `location()` is what the Hetzner adapter calls, and it must agree
        // with MachineConfig's own accessor for a machine that declares none.
        assert_eq!(machine_facts(&machine("static-1")).location(), "");
    }
}
